// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {LiquidityPool} from "../src/LiquidityPool.sol";

contract InvMutTest is Test {
    LiquidityPool c;
    function setUp() public { c = new LiquidityPool(0, bytes16(0), address(this), address(this), address(this)); }
    function testFuzz_property(address caller, uint128 price) public {
        vm.assume(caller != address(this));
        uint128 beforePrice = c.latestPrice();
        vm.prank(caller);
        bool reverted = false;
        try c.updatePrice(price) { reverted = false; } catch { reverted = true; }
        uint128 afterPrice = c.latestPrice();
        assertTrue(reverted || afterPrice == beforePrice);
    }
}
